SELECT format('GRANT USAGE ON FOREIGN DATA WRAPPER %I TO %I', w.fdwname, r.rolname) FROM pg_foreign_data_wrapper w JOIN pg_depend d ON d.classid = 'pg_foreign_data_wrapper'::regclass AND d.objid = w.oid AND d.deptype = 'e' CROSS JOIN pg_roles r WHERE r.rolcanlogin AND NOT r.rolsuper AND r.rolname !~ '^pg_' AND has_database_privilege(r.oid, current_database(), 'CREATE')@isset($role) AND r.rolname = {!! $sql->string($role) !!}@endisset \gexec
SELECT format('GRANT USAGE ON SCHEMA cron TO %I', r.rolname) FROM pg_roles r WHERE EXISTS (SELECT FROM pg_namespace WHERE nspname = 'cron') AND r.rolcanlogin AND NOT r.rolsuper AND r.rolname !~ '^pg_' AND has_database_privilege(r.oid, current_database(), 'CREATE')@isset($role) AND r.rolname = {!! $sql->string($role) !!}@endisset \gexec
